<?php
require __DIR__.'/config/bootstrap.php';
if(is_logged_in()) redirect('index.php');
$error=''; verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
    $identity=trim($_POST['identity']??'');$password=$_POST['password']??'';
    try{$q=db()->prepare("SELECT id,username,email,password,role,status FROM users WHERE (email=? OR username=?) LIMIT 1");$q->execute([$identity,$identity]);$user=$q->fetch();
        if($user&&$user['status']==='active'&&password_verify($password,$user['password'])){session_regenerate_id(true);unset($user['password']);$_SESSION['user']=$user;$_SESSION['last_activity']=time();log_activity('Login','Signed in');redirect('index.php');}
        $error='Those sign-in details don’t match an active account.';
    }catch(Throwable){$error='EMS could not connect to its database. Import database/ems.sql and check config/database.php.';}
}
$flashes=take_flashes();
